#include <bits/stdc++.h>
using namespace std;
typedef __int128 i128;

// parse a plain decimal with at most 6 fractional digits into an integer scaled by 10^6
long long scaled(const string &s) {
    size_t p = 0;
    int sign = 1;
    if (s[p] == '+' || s[p] == '-') { if (s[p] == '-') sign = -1; p++; }
    long long whole = 0, frac = 0;
    while (p < s.size() && s[p] != '.') whole = whole * 10 + (s[p++] - '0');
    int digits = 0;
    if (p < s.size()) for (p++; p < s.size(); p++, digits++) frac = frac * 10 + (s[p] - '0');
    for (; digits < 6; digits++) frac *= 10;
    return sign * (whole * 1000000 + frac);
}

string toStr(i128 v) {
    if (v == 0) return "0";
    string s;
    while (v > 0) { s += char('0' + (int)(v % 10)); v /= 10; }
    reverse(s.begin(), s.end());
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<pair<long long, long long>> pts(n);
    string a, b;
    for (auto &p : pts) { cin >> a >> b; p = {scaled(a), scaled(b)}; }
    sort(pts.begin(), pts.end());
    vector<long long> xs(n);
    for (int i = 0; i < n; i++) xs[i] = pts[i].first;
    string out;
    for (int t = 0; t < q; t++) {
        cin >> a;
        long long x = scaled(a);
        int i = int(upper_bound(xs.begin(), xs.end(), x) - xs.begin()) - 1;
        i = max(0, min(n - 2, i));
        auto [xa, ya] = pts[i];
        auto [xb, yb] = pts[i + 1];
        i128 den = xb - xa;
        i128 num = (i128)ya * den + (i128)(yb - ya) * (x - xa);
        bool neg = num < 0;
        if (neg) num = -num;
        // exact value num/den in micro-units, rounded half away from zero
        i128 units = num / den, rem = num % den;
        if (2 * rem >= den) units++;
        if (units == 0) neg = false;
        string part = to_string((long long)(units % 1000000));
        out += (neg ? "-" : "") + toStr(units / 1000000) + "." + string(6 - part.size(), '0') + part + "\n";
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    // read a plain decimal with at most 6 fractional digits as an integer scaled by 10^6
    static long nextScaled() throws IOException {
        int c = read();
        while (c == ' ' || c == '\t' || c == '\n' || c == '\r') c = read();
        long sign = 1;
        if (c == '+' || c == '-') { if (c == '-') sign = -1; c = read(); }
        long whole = 0, frac = 0;
        while (c >= '0' && c <= '9') { whole = whole * 10 + c - '0'; c = read(); }
        int digits = 0;
        if (c == '.') {
            c = read();
            while (c >= '0' && c <= '9') { frac = frac * 10 + c - '0'; digits++; c = read(); }
        }
        for (; digits < 6; digits++) frac *= 10;
        return sign * (whole * 1000000 + frac);
    }

    public static void main(String[] args) throws IOException {
        int n = (int) (nextScaled() / 1000000), q = (int) (nextScaled() / 1000000);
        long[][] pts = new long[n][];
        for (int i = 0; i < n; i++) pts[i] = new long[]{nextScaled(), nextScaled()};
        Arrays.sort(pts, (p, r) -> Long.compare(p[0], r[0]));
        long[] xs = new long[n];
        for (int i = 0; i < n; i++) xs[i] = pts[i][0];
        StringBuilder sb = new StringBuilder();
        BigInteger million = BigInteger.valueOf(1000000);
        for (int t = 0; t < q; t++) {
            long x = nextScaled();
            // last index with xs[i] <= x, clamped to a valid segment start
            int lo = 0, hi = n;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (xs[mid] <= x) lo = mid + 1; else hi = mid; }
            int i = Math.max(0, Math.min(n - 2, lo - 1));
            long xa = pts[i][0], ya = pts[i][1], xb = pts[i + 1][0], yb = pts[i + 1][1];
            BigInteger den = BigInteger.valueOf(xb - xa);
            BigInteger num = BigInteger.valueOf(ya).multiply(den)
                    .add(BigInteger.valueOf(yb - ya).multiply(BigInteger.valueOf(x - xa)));
            boolean neg = num.signum() < 0;
            // exact value num/den in micro-units, rounded half away from zero
            BigInteger[] qr = num.abs().divideAndRemainder(den);
            BigInteger units = qr[0];
            if (qr[1].shiftLeft(1).compareTo(den) >= 0) units = units.add(BigInteger.ONE);
            if (units.signum() == 0) neg = false;
            BigInteger[] wp = units.divideAndRemainder(million);
            String part = wp[1].toString();
            if (neg) sb.append('-');
            sb.append(wp[0]).append('.');
            for (int k = part.length(); k < 6; k++) sb.append('0');
            sb.append(part).append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"math/big"
	"os"
	"sort"
	"strings"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

// read a plain decimal with at most 6 fractional digits as an integer scaled by 10^6
func nextScaled() int64 {
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\t' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	sign := int64(1)
	if c == '+' || c == '-' {
		if c == '-' {
			sign = -1
		}
		c, _ = rd.ReadByte()
	}
	var whole, frac int64
	for c >= '0' && c <= '9' {
		whole = whole*10 + int64(c-'0')
		c, _ = rd.ReadByte()
	}
	digits := 0
	if c == '.' {
		c, _ = rd.ReadByte()
		for c >= '0' && c <= '9' {
			frac = frac*10 + int64(c-'0')
			digits++
			c, _ = rd.ReadByte()
		}
	}
	for ; digits < 6; digits++ {
		frac *= 10
	}
	return sign * (whole*1000000 + frac)
}

func main() {
	n, q := int(nextScaled()/1000000), int(nextScaled()/1000000)
	pts := make([][2]int64, n)
	for i := range pts {
		pts[i][0] = nextScaled()
		pts[i][1] = nextScaled()
	}
	sort.Slice(pts, func(i, j int) bool { return pts[i][0] < pts[j][0] })
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	million := big.NewInt(1000000)
	num, t, den, rem, units, part := new(big.Int), new(big.Int), new(big.Int), new(big.Int), new(big.Int), new(big.Int)
	for ; q > 0; q-- {
		x := nextScaled()
		i := sort.Search(n, func(k int) bool { return pts[k][0] > x }) - 1
		i = max(0, min(n-2, i))
		xa, ya, xb, yb := pts[i][0], pts[i][1], pts[i+1][0], pts[i+1][1]
		den.SetInt64(xb - xa)
		num.Mul(big.NewInt(ya), den)
		t.Mul(big.NewInt(yb-ya), big.NewInt(x-xa))
		num.Add(num, t)
		neg := num.Sign() < 0
		num.Abs(num)
		// exact value num/den in micro-units, rounded half away from zero
		units.QuoRem(num, den, rem)
		if rem.Lsh(rem, 1).Cmp(den) >= 0 {
			units.Add(units, big.NewInt(1))
		}
		if units.Sign() == 0 {
			neg = false
		}
		units.QuoRem(units, million, part)
		if neg {
			w.WriteByte('-')
		}
		w.WriteString(units.String())
		w.WriteByte('.')
		ps := part.String()
		w.WriteString(strings.Repeat("0", 6-len(ps)))
		w.WriteString(ps)
		w.WriteByte('\n')
	}
}
